  "name": "fullstack-web-app",
  "private": true,
  "type": "module",
  "scripts": { "start": "node server/index.js", "dev": "node --watch server/index.js" },
  "dependencies": { "express": "^5.1.0", "sql.js": "^1.13.0" }
